/**
 * The `scholarly_search` tool: multi-source literature retrieval across 7 academic indexes.
 * Supports intelligent routing, weighted RRF fusion, collision check against Zotero, and background promotion.
 * @module dsh-zotero/scholarly/tools/search
 */

import { type ToolDefinition } from '@deepseek-ai/dsh-tools'
import { defineZoteroTool as defineTool } from '../../define-tool.js'
import {
  formatPaperItem,
  fuseRankedLists,
  postProcessRanked,
  type RankedSourceList,
} from '../fusion.js'
import { routeQuery } from '../router.js'
import { SOURCE_SEARCHERS } from '../sources/index.js'
import { SCHOLARLY_SOURCE_IDS, SCHOLARLY_SOURCE_NAMES, type ScholarlyQuery } from '../types.js'
import { annotateWithLibraryStatus } from '../zotero-link.js'
import { ZoteroError, ZOTERO_INVALID_ARGUMENT } from '../../errors.js'
import {
  allSourcesFailedText,
  failureTextOf,
  isLocalAddressRejection,
  someSourcesFailedText,
} from './failure.js'
import { presentJobArm, RUN_IN_BACKGROUND_PARAMETER } from '../../job-runner.js'
import { metaRecordOf } from '../../tools/present.js'
import { SCHOLARLY_JOB_OUTPUT_DESCRIPTOR, runScholarlyJob } from './jobs.js'
import { toCleanJsonRecords, type ScholarlyToolHost } from './common.js'

const CITE_HINT = 'Tip: Cite a paper from these results using its title link or ID.'

/** Sources whose ranked lists get the boosted RRF weight (1.2 instead of 1.0). */
const BOOSTED_RRF_SOURCES: ReadonlySet<string> = new Set(['arxiv', 'dblp', 'pubmed', 'europepmc'])

export function createScholarlySearchTool(
  host: ScholarlyToolHost,
  options: { readonly background?: boolean } = {},
): ToolDefinition {
  const background = options.background ?? true
  return defineTool({
    name: 'scholarly_search',
    description:
      'Search global scholarly literature across arXiv, OpenAlex, Crossref, Semantic Scholar, PubMed, Europe PMC, and DBLP. ' +
      'Deduplicates records across indexes into unified entries with citations, open-access status, and local Zotero library markers. ' +
      'Use this for academic papers, preprints, and journals (not general web pages).',
    parameters: {
      query: {
        type: 'string',
        required: true,
        description: 'Topic keywords, a paper title, or author with topic in English.',
      },
      sources: {
        type: 'array',
        items: { type: 'string', enum: [...SCHOLARLY_SOURCE_IDS] },
        description:
          'Optional: limit to specific indexes. Default routes automatically by topic keyword semantics.',
      },
      year_from: {
        type: 'integer',
        description:
          'Published in this year or later. If omitted with sort="date", defaults to the previous year.',
      },
      year_to: { type: 'integer', description: 'Published in this year or earlier.' },
      open_access: { type: 'boolean', description: 'Only return papers with free full text.' },
      sort: {
        type: 'string',
        enum: ['relevance', 'date', 'citations'],
        default: 'relevance',
        description:
          'Order: relevance; date (arXiv: submitted date; others: newest within top min(50,3*limit) relevance hits); citations (most cited first).',
      },
      categories: {
        type: 'array',
        items: { type: 'string' },
        description: 'arXiv categories like cs.CL, stat.ML (applies to arXiv).',
      },
      limit: { type: 'integer', default: 8, description: 'How many papers to return (default 8).' },
      abstract: {
        type: 'string',
        enum: ['none', 'snippet', 'full'],
        default: 'snippet',
        description: 'How much abstract to display in the text summary.',
      },
      ...(background ? RUN_IN_BACKGROUND_PARAMETER : {}),
    },
    output: SCHOLARLY_JOB_OUTPUT_DESCRIPTOR,
    isConcurrencySafe: () => true,
    timeoutMs: 180_000,
    async execute(args, exec) {
      const text = args.query.trim()
      if (!text) throw new ZoteroError('query parameter cannot be empty.', ZOTERO_INVALID_ARGUMENT)

      const limit = Math.min(
        host.maxResults(),
        Math.max(1, args.limit ?? Math.min(8, host.maxResults())),
      )
      const selectedSources = routeQuery(text, args.sources)
      const thisYear = new Date().getFullYear()
      const isDateSort = args.sort === 'date'

      const yearFrom = args.year_from ?? (isDateSort ? thisYear - 1 : undefined)
      const yearTo =
        yearFrom === undefined && args.year_to === undefined
          ? undefined
          : (args.year_to ?? thisYear + 1)

      const queryObj: ScholarlyQuery = {
        query: text,
        sort: args.sort === 'citations' ? 'relevance' : (args.sort ?? 'relevance'),
        limit: Math.min(
          50,
          args.sort === 'citations'
            ? limit * 4
            : selectedSources.length === 1
              ? limit
              : Math.max(5, Math.ceil(limit * 0.8)),
        ),
        ...(yearFrom !== undefined ? { yearFrom } : {}),
        ...(yearTo !== undefined ? { yearTo } : {}),
        ...(args.open_access ? { openAccess: true } : {}),
        ...(args.categories && args.categories.length > 0 ? { categories: args.categories } : {}),
      }

      return await runScholarlyJob({
        host,
        exec,
        label: `scholarly_search (${selectedSources.length} sources)`,
        runInBackground: args.run_in_background === true,
        run: async (signal, onProgress) => {
          const keys = await host.keys()
          const failedSources: string[] = []
          /** Failures whose cause is the local address gate, not the index. */
          let localRejections = 0

          const sourceResults = await Promise.all(
            selectedSources.map(async (sourceId, index) => {
              try {
                // Total over `ScholarlySourceId`: the registry and the id union are
                // declared together, so this lookup cannot be undefined.
                const searcher = SOURCE_SEARCHERS[sourceId]
                const queryForSource =
                  isDateSort && sourceId !== 'arxiv'
                    ? { ...queryObj, sort: 'relevance' as const, limit: Math.min(50, limit * 3) }
                    : queryObj

                const papers = await searcher(queryForSource, host.http, keys, signal)
                const weight = BOOSTED_RRF_SOURCES.has(sourceId) ? 1.2 : 1.0
                onProgress({
                  phase: 'source',
                  current: index + 1,
                  total: selectedSources.length,
                  message: `${SCHOLARLY_SOURCE_NAMES[sourceId]}: ${papers.length} hits`,
                })

                return {
                  sourceId,
                  weight,
                  papers,
                } satisfies RankedSourceList
              } catch (error) {
                if (signal.aborted) throw error
                if (isLocalAddressRejection(error)) localRejections += 1
                failedSources.push(`${SCHOLARLY_SOURCE_NAMES[sourceId]} (${failureTextOf(error)})`)
                return {
                  sourceId,
                  weight: 1.0,
                  papers: [],
                } satisfies RankedSourceList
              }
            }),
          )

          // 1. Fuse multiple ranked lists with Match Lattice & Weighted RRF
          let papers = fuseRankedLists(sourceResults)

          // 2. Post-process rankings (title exact match, date/citation sorting, OA filter, limit slice)
          papers = postProcessRanked(papers, { ...queryObj, limit, sort: args.sort ?? 'relevance' })

          // 3. Cross-component collision check against the local Zotero library (top N only).
          //    A lookup that could not run reports "unavailable" instead of leaving
          //    hits unmarked, where a reader would take them for "not held".
          const { notice: libraryNotice } = await annotateWithLibraryStatus(
            papers,
            host.zoteroService?.(),
            signal,
          )

          if (papers.length === 0) {
            const attempted = selectedSources.map((s) => SCHOLARLY_SOURCE_NAMES[s]).join(', ')
            if (failedSources.length === selectedSources.length && selectedSources.length > 0) {
              return {
                text: allSourcesFailedText(
                  'these keywords',
                  text,
                  failedSources,
                  localRejections === failedSources.length,
                ),
                papers: [],
                issues: failedSources,
              }
            }
            const failureNotice =
              failedSources.length > 0
                ? `\nUnanswered sources: ${failedSources.join('; ')}. No match came from the ${selectedSources.length - failedSources.length} source(s) that answered. ${someSourcesFailedText(localRejections, failedSources.length)}`
                : ''
            return {
              text: `No papers found for "${text}" across ${attempted}.${failureNotice} Try fewer or alternative keywords.`,
              papers: [],
              issues: failedSources,
            }
          }

          const answeredSources = selectedSources
            .filter((_, idx) => sourceResults[idx]!.papers.length > 0)
            .map((s) => SCHOLARLY_SOURCE_NAMES[s])

          const abstractChars = args.abstract === 'none' ? 0 : args.abstract === 'full' ? 4000 : 300
          const summaryHeader = `${papers.length} papers found for "${text}" (via ${answeredSources.join(
            ', ',
          )}).`
          const failureNote =
            failedSources.length > 0 ? `\nNotice: ${failedSources.join('; ')}.` : ''

          const formattedLines = papers
            .map((p, idx) => formatPaperItem(p, idx + 1, abstractChars))
            .join('\n\n')

          return {
            text: `${summaryHeader}${failureNote}${libraryNotice}\n${CITE_HINT}\n\n${formattedLines}`,
            papers: toCleanJsonRecords(papers),
            issues: failedSources,
          }
        },
      })
    },
    presentCall: (args) => ({
      card: 'generic',
      title: 'Search scholarly literature',
      rawInput: String(args.query ?? ''),
      kind: 'search',
    }),
    presentResult: (_args, result) => presentJobArm('Scholarly search', metaRecordOf(result) ?? {}),
  })
}
